<script setup>
import {shallowRef,onMounted,onUnmounted,watch} from 'vue'
import {t,locale} from '../i18n'
const props=defineProps({type:{type:String,default:'candles'},price:{type:Number,default:60742.62},interval:{type:String,default:"trade.interval_1h"}})
const canvas=shallowRef(null);let observer
function draw(){const c=canvas.value;if(!c)return;const w=c.clientWidth,h=c.clientHeight,dpr=window.devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const left=12,right=w-68,top=28,bottom=h-90,span=right-left;ctx.font='11px "Exo 2", sans-serif';ctx.strokeStyle='#ffffff0c';ctx.fillStyle='#ffffff70';ctx.lineWidth=1;ctx.setLineDash([2,3]);for(let i=0;i<7;i++){const y=top+(bottom-top)*i/6;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();if(props.type==='candles')ctx.fillText((props.price*(1.08-i*.025)).toLocaleString('en-US',{maximumFractionDigits:props.price<1?8:0}),right+7,y+4)}for(let i=0;i<5;i++){const x=left+span*i/4;ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,bottom+55);ctx.stroke();ctx.fillText(props.type==='line'?['D−60','D−30','D−10','NOW',''][i]:['11-21','11-22','11-23','11-24',''][i],x,bottom+76)}ctx.setLineDash([]);if(props.type==='line'){for(let line=0;line<6;line++){ctx.strokeStyle=line===0?'#a5ff4a':'#ffffff18';ctx.lineWidth=line===0?2:1;ctx.beginPath();for(let i=0;i<60;i++){const x=left+i/59*span,y=bottom-(bottom-top)*(.12+i/59*(.7-line*.09)+Math.sin(i*.18+line)*.025);i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}return}const n=110,step=span/n,shift=props.interval.length*.35;for(let i=0;i<n;i++){const trend=.36+Math.sin(i*.045)*.15+Math.exp(-(((i-26)/9)**2))*.33-Math.exp(-(((i-93)/4)**2))*.17;const open=trend+Math.sin(i*1.7+shift)*.025,close=trend+Math.sin(i*2.5+shift)*.025,y1=top+(bottom-top)*open,y2=top+(bottom-top)*close,x=left+i*step,color=close<open?'#5bbb91':'#e34a68';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,Math.min(y1,y2)-6);ctx.lineTo(x,Math.max(y1,y2)+7);ctx.stroke();ctx.fillRect(x-step*.3,Math.min(y1,y2),Math.max(1,step*.6),Math.max(1,Math.abs(y2-y1)));ctx.fillRect(x-step*.3,bottom+55,Math.max(1,step*.6),-(10+Math.abs(Math.sin(i*1.7))*35))}for(let line=0;line<3;line++){ctx.strokeStyle=['#c8b04b','#a54a9d','#6855bf'][line];ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<n;i++){const v=.36+Math.sin(i*.045)*(.15-line*.04)+Math.exp(-(((i-26)/14)**2))*(.25-line*.07),x=left+i*step,y=top+(bottom-top)*(v-line*.03);i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}const py=top+(bottom-top)*.4;ctx.fillStyle='#75dca3';ctx.fillRect(right,py-10,68,20);ctx.fillStyle='#07100b';ctx.fillText(props.price.toFixed(props.price<1?8:2),right+4,py+4);ctx.fillStyle='#ffffff80';ctx.fillText(t("chart.ui.ma7Ma25Ma99K"),12,15)}
onMounted(()=>{observer=new ResizeObserver(draw);observer.observe(canvas.value);draw()});watch(()=>[props.price,props.interval,props.type,locale.value],draw);onUnmounted(()=>observer?.disconnect())
</script>
<template><canvas ref="canvas" class="price-chart" role="img" :aria-label="type==='line'?$t(&quot;chart.ui.message&quot;):$t(&quot;chart.ui.simulatedCandlestickChart&quot;)+' · '+price+' · '+$t(interval)"></canvas></template>
<style scoped>.price-chart{display:block;width:100%;height:100%;min-height:300px}</style>
